const assert=require('node:assert/strict');
const fs=require('node:fs');
const path=require('node:path');
const root=path.resolve(__dirname,'../..');
function source(p){return fs.readFileSync(path.join(root,p),'utf8')}
function moduleFrom(p,names){return new Function(source(p).replace(/export\s+(?=(?:async\s+)?(?:function|const|let|class)\s)/g,'')+'\nreturn {'+names.join(',')+'};')();}
const tax=moduleFrom('remarkTaxonomy.js',['REMARK_CATEGORIES','categoryForRemark','storedCategory','categoryRank']);
assert.deepEqual(tax.REMARK_CATEGORIES,[
  'Remarques générales','Entretien P2','Travaux de conformité','Travaux d’amélioration']);
assert.equal(tax.categoryForRemark('Travaux P2'),'Entretien P2');
assert.equal(tax.categoryForRemark('Travaux d’amélioration'),'Travaux d’amélioration');
assert.equal(tax.categoryForRemark('Conformité Local'),'Travaux de conformité');
assert.equal(tax.categoryForRemark('Entretien / P3'),'Remarques générales');
assert.equal(tax.storedCategory('Remarques générales'),'Observation');
assert.equal(tax.categoryRank('Travaux P2'),1);
const cta=moduleFrom('remarCtaDirection.js',['isSupplyOnlyCta','shouldShowCtaField']);
assert.equal(cta.isSupplyOnlyCta('CTA Soufflage'),true);
assert.equal(cta.isSupplyOnlyCta('CTA soufflage / extraction'),false);
assert.equal(cta.shouldShowCtaField('CTA Soufflage','CTA','Extraction / Reprise'),false);
assert.equal(cta.shouldShowCtaField('CTA Soufflage','CTA','Consigne soufflage'),true);
assert.equal(cta.shouldShowCtaField('CTA double flux','CTA','Extraction'),true);
const ecs=moduleFrom('ecsNetworkTemperatures.js',['isEcsLoopNetwork','ecsTemperatureSummary']);
assert.equal(ecs.isEcsLoopNetwork('Boucle ECS'),true);
assert.equal(ecs.isEcsLoopNetwork('Réseau chauffage'),false);
assert.equal(ecs.ecsTemperatureSummary({t_dep_c:'60',t_retour_ecs_c:'53',t_stockage_ecs_c:'62'}),
  'Départ 60 °C · Retour 53 °C · Stockage 62 °C');
const migration=source('database/migrations/050_ecs_loop_return_temperature.js');
assert.ok(migration.includes('ALTER TABLE reseaux ADD COLUMN t_retour_ecs_c TEXT'));
assert.ok(source('database/migrations/index.js').includes('migration050'));
assert.ok(source('database/migrations/index.js').includes('migration051'));
assert.ok(source('database/migrations/051_ecs_storage_temperature.js').includes('ALTER TABLE reseaux ADD COLUMN t_stockage_ecs_c TEXT'));
assert.ok(source('database/migrations/051_ecs_storage_temperature.js').includes('ALTER TABLE observations_reseau ADD COLUMN t_stockage_ecs_c TEXT'));
assert.ok(source('database/constants.js').includes('DATABASE_SCHEMA_VERSION = 51'));
assert.ok(source('visitCarryForwardDb.js').includes('row.t_stockage_ecs_c ?? null'));
assert.ok(source('visitCarryForwardDb.js').includes('row.t_retour_ecs_c ?? null'));
const reg=source('OptimizedRegulationPanel.js');
assert.ok(reg.includes('label="Température Retour"'));
assert.ok(reg.includes('label="Température de Stockage"'));
assert.ok(reg.includes('label="Température Départ"'));
assert.ok(reg.includes('setStockageEcs'));
assert.ok(reg.includes('isEcsLoop ? <>'));
assert.ok(reg.includes('isEcsLoop ? <TileRow>'));
const networkDb=source('db.js');
assert.ok(networkDb.includes("'t_retour_ecs_c'"));
assert.ok(networkDb.includes("'t_stockage_ecs_c'"));
const report=source('reportBuilder.js'),xls=source('excelExport.js');
assert.ok(report.includes("comment:reseau.t_retour_ecs_c||''"));
assert.ok(report.includes("comment:r.t_retour_ecs_c||''"));
assert.ok(report.includes("comment:r.t_stockage_ecs_c||''"));
assert.ok(report.includes("comment:reseau.t_stockage_ecs_c||''"));
assert.ok(xls.includes("T° retour ECS (°C)"));
assert.ok(xls.includes("T° stockage ECS (°C)"));
assert.ok(source('excelImport.js').includes('tStockageEcs'));
assert.ok(source('intranetVisitPayload.js').includes("['t_stockage_ecs_c','Température de stockage ECS','°C']"));
const ui=source('OptimizedRemarksPanel.js');
assert.ok(ui.includes("Urgence / criticité"));
assert.ok(ui.includes("REMARK_CATEGORIES.map"));
const swipe=source('VisiteScreen.js');
assert.ok(swipe.includes('onPanResponderTerminationRequest: () => true'));
assert.ok(swipe.includes('onPanResponderReject: () => { transitionRef.current = false; }'));
const panel=source('RemarDynamicPanel.js');
assert.ok(panel.includes('shouldShowCtaField(equipment.designation'));
assert.ok(!panel.includes("'CTA extraction'"),'CTA extraction removed from presets');
assert.ok(source('remarDynamicDb.js').includes("famille === 'cta' && isStandaloneExtractionCtaName(label)"));
assert.ok(source('remarDynamicDb.js').includes('Utilise un caisson VMC'));
console.log('PASS 25+ CROUS feedback rules, separate ECS return, reporting, reserve sorting, CTA direction and swipe safety');
